16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.BusinessDay;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "postcode")
66	    private String postcode;
67	
68	    @Column(name = "registration_date", columnDefinition = "DATE")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date", columnDefinition = "DATE")
72	    private LocalDate birthDate;
73	
74	    @Column(name = "customer_code")
75	    private String customerCode;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "household_size")
84	    private Integer householdSize;
85	
86	    @Column(name = "bulk_signup_warning")
87	    private boolean bulkSignupWarning;
88	
89	    @Column(name = "possible_duplicate")
90	    private boolean possibleDuplicate;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted")
96	    private boolean deleted;
97	
98	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
99	    private Set<Pet> pets;
100	
101	    public String getTitle() {
102	        return this.title;
103	    }
104	
105	    public void setTitle(String title) {
106	        this.title = title;
107	    }
108	
109	    /**
110	     * The owner's salutation: the {@link #title} followed by a space and the last name when a title
111	     * is supplied, otherwise just the last name.
112	     */
113	    @Transient
114	    public String getSalutation() {
115	        return (this.title == null || this.title.isBlank())
116	            ? this.lastName
117	            : this.title + " " + this.lastName;
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getAddressLine1() {
129	        return this.addressLine1;
130	    }
131	
132	    public void setAddressLine1(String addressLine1) {
133	        this.addressLine1 = addressLine1;
134	    }
135	
136	    public String getAddressLine2() {
137	        return this.addressLine2;
138	    }
139	
140	    public void setAddressLine2(String addressLine2) {
141	        this.addressLine2 = addressLine2;
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    public String getEmail() {
161	        return this.email;
162	    }
163	
164	    /**
165	     * Stores the email in its canonical lower-cased form so it is always persisted and
166	     * returned lower-cased, regardless of the casing supplied by the client.
167	     */
168	    public void setEmail(String email) {
169	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
170	    }
171	
172	    public String getPostcode() {
173	        return this.postcode;
174	    }
175	
176	    public void setPostcode(String postcode) {
177	        this.postcode = postcode;
178	    }
179	
180	    public LocalDate getRegistrationDate() {
181	        return this.registrationDate;
182	    }
183	
184	    public void setRegistrationDate(LocalDate registrationDate) {
185	        this.registrationDate = registrationDate;
186	    }
187	
188	    public LocalDate getBirthDate() {
189	        return this.birthDate;
190	    }
191	
192	    public void setBirthDate(LocalDate birthDate) {
193	        this.birthDate = birthDate;
194	    }
195	
196	    /**
197	     * The owner's tenure in days: the number of whole days from its {@link #registrationDate} to
198	     * the current date. A brand-new owner registered today has zero tenure.
199	     */
200	    @Transient
201	    public long getTenureDays() {
202	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
203	    }
204	
205	    /**
206	     * The owner's age band derived from {@link #birthDate} against {@link #registrationDate}, or
207	     * {@code null} when no birth date was supplied.
208	     */
209	    @Transient
210	    public AgeBand getAgeBand() {
211	        return this.birthDate == null ? null : AgeBand.of(this.birthDate, this.registrationDate);
212	    }
213	
214	    public String getCustomerCode() {
215	        return this.customerCode;
216	    }
217	
218	    public void setCustomerCode(String customerCode) {
219	        this.customerCode = customerCode;
220	    }
221	
222	    public String getHouseholdId() {
223	        return this.householdId;
224	    }
225	
226	    public void setHouseholdId(String householdId) {
227	        this.householdId = householdId;
228	    }
229	
230	    public Integer getNamesakeCount() {
231	        return this.namesakeCount;
232	    }
233	
234	    public void setNamesakeCount(Integer namesakeCount) {
235	        this.namesakeCount = namesakeCount;
236	    }
237	
238	    public Integer getHouseholdSize() {
239	        return this.householdSize;
240	    }
241	
242	    public void setHouseholdSize(Integer householdSize) {
243	        this.householdSize = householdSize;
244	    }
245	
246	    public boolean isBulkSignupWarning() {
247	        return this.bulkSignupWarning;
248	    }
249	
250	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
251	        this.bulkSignupWarning = bulkSignupWarning;
252	    }
253	
254	    public boolean isPossibleDuplicate() {
255	        return this.possibleDuplicate;
256	    }
257	
258	    public void setPossibleDuplicate(boolean possibleDuplicate) {
259	        this.possibleDuplicate = possibleDuplicate;
260	    }
261	
262	    public Integer getPossibleDuplicateOf() {
263	        return this.possibleDuplicateOf;
264	    }
265	
266	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
267	        this.possibleDuplicateOf = possibleDuplicateOf;
268	    }
269	
270	    /**
271	     * Whether this owner has been soft-deleted: the record is retained but flagged so it is
272	     * excluded from the create endpoint's duplicate and identity checks. A newly created owner
273	     * is not deleted.
274	     */
275	    public boolean isDeleted() {
276	        return this.deleted;
277	    }
278	
279	    public void setDeleted(boolean deleted) {
280	        this.deleted = deleted;
281	    }
282	
283	    /**
284	     * The derived key that uniquely identifies an owner for duplicate detection: the normalized
285	     * telephone, the (lower-cased) email or the empty string when absent, and the household id or
286	     * the empty string when the owner belongs to no household, joined with {@code '|'}. Two owners
287	     * are duplicates only when their whole identity keys are equal, so members of the same household
288	     * with different telephones (or an owner reusing only a telephone or only an email) remain
289	     * distinct.
290	     */
291	    @Transient
292	    public String getIdentityKey() {
293	        return this.telephone + "|"
294	            + (this.email == null ? "" : this.email) + "|"
295	            + (this.householdId == null ? "" : this.householdId);
296	    }
297	
298	    /**
299	     * On first persist, default the registration date to the server's current date when the
300	     * client did not supply one, then roll the effective date forward so it always falls on a
301	     * business day (a weekend moves to the following Monday).
302	     */
303	    @PrePersist
304	    private void defaultRegistrationDate() {
305	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
306	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
307	    }
308	
309	    protected Set<Pet> getPetsInternal() {
310	        if (this.pets == null) {
311	            this.pets = new HashSet<>();
312	        }
313	        return this.pets;
314	    }
315	
316	    protected void setPetsInternal(Set<Pet> pets) {
317	        this.pets = pets;
318	    }
319	
320	    public List<Pet> getPets() {
321	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
322	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
323	        return Collections.unmodifiableList(sortedPets);
324	    }
325	
326	    public void setPets(List<Pet> pets) {
327	        this.pets = new HashSet<>(pets);
328	    }
329	
330	    public void addPet(Pet pet) {
331	        getPetsInternal().add(pet);
332	        pet.setOwner(this);
333	    }
334	
335	    /**
336	     * Return the Pet with the given name, or null if none found for this Owner.
337	     *
338	     * @param name to test
339	     * @return true if pet name is already in use
340	     */
341	    public Pet getPet(String name) {
342	        return getPet(name, false);
343	    }
344	
345	    /**
346	     * Return the Pet with the given name, or null if none found for this Owner.
347	     *
348	     * @param name to test
349	     * @return true if pet name is already in use
350	     */
351	    public Pet getPet(String name, boolean ignoreNew) {
352	        name = name.toLowerCase();
353	        for (Pet pet : getPetsInternal()) {
354	            if (!ignoreNew || !pet.isNew()) {
355	                String compName = pet.getName();
356	                compName = compName.toLowerCase();
357	                if (compName.equals(name)) {
358	                    return pet;
359	                }
360	            }
361	        }
362	        return null;
363	    }
364	
365	    public Pet getPet(Integer petId) {
366	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
367	    }
368	
369	    @Override
370	    public String toString() {
371	        return new ToStringCreator(this)
372	
373	            .append("id", this.getId())
374	            .append("new", this.isNew())
375	            .append("lastName", this.getLastName())
376	            .append("firstName", this.getFirstName())
377	            .append("address", this.address)
378	            .append("city", this.city)
379	            .append("telephone", this.telephone)
380	            .append("email", this.email)
381	            .toString();
382	    }
383	}
