67	    /** The upper-cased first letter of {@code name} followed by a dot. */
68	    private String initial(String name) {
69	        return Character.toUpperCase(name.charAt(0)) + ".";
70	    }
71	
72	    /**
73	     * Derives the owner's locality (canonical region) from the leading {@code <REGION>} segment of
74	     * its {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality always agrees with the
75	     * region encoded in the owner's identity.
