226	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
227	        ownerPageDto.setPage(ownerPage.getNumber());
228	        ownerPageDto.setSize(ownerPage.getSize());
229	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
230	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
231	        return ownerPageDto;
232	    }
233	}
